func Or(predicates ...predicate.PayPayment) predicate.PayPayment {
	return predicate.PayPayment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PayPayment) predicate.PayPayment {
	return predicate.PayPayment(sql.NotPredicates(p))
}
